{"task": "customer-fk", "steps": [
  {"note": "Add the foreign key as NOT VALID: no table scan, only a brief SHARE ROW EXCLUSIVE lock on orders and customers. lock_timeout 500ms so app queries never queue behind us for long (app statement_timeout is 2s); retry up to 60 times if the lock isn't free. New and updated rows are checked from this point on.",
   "sql": "SET lock_timeout = '500ms'; SET statement_timeout = '10s'; DO $$ DECLARE i int; BEGIN IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_customer_id_fkey' AND conrelid = 'orders'::regclass) THEN RETURN; END IF; FOR i IN 1..60 LOOP BEGIN ALTER TABLE orders ADD CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers (id) NOT VALID; RETURN; EXCEPTION WHEN lock_not_available THEN RAISE NOTICE 'lock busy, attempt % of 60', i; PERFORM pg_sleep(1); END; END LOOP; RAISE EXCEPTION 'could not get the lock to add orders_customer_id_fkey after 60 attempts'; END $$;"},
  {"note": "Validate the existing 10M rows. VALIDATE takes only SHARE UPDATE EXCLUSIVE on orders and ROW SHARE on customers, so app reads and inserts keep running during the scan. No statement timeout for the scan; retry if the lock is briefly held (for example by autovacuum).",
   "sql": "SET lock_timeout = '5s'; SET statement_timeout = 0; DO $$ DECLARE i int; BEGIN FOR i IN 1..20 LOOP BEGIN ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_id_fkey; RETURN; EXCEPTION WHEN lock_not_available THEN RAISE NOTICE 'lock busy, attempt % of 20', i; PERFORM pg_sleep(2); END; END LOOP; RAISE EXCEPTION 'could not get the lock to validate orders_customer_id_fkey after 20 attempts'; END $$;"},
  {"note": "Check that the constraint exists and is validated.",
   "sql": "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'orders_customer_id_fkey' AND conrelid = 'orders'::regclass AND contype = 'f' AND convalidated) THEN RAISE EXCEPTION 'orders_customer_id_fkey is missing or not validated'; END IF; END $$;"}
]}
